            int complementCount = remainderCount.getOrDefault(complement, 0);
            if (count != complementCount) {
                return false;
            }
        }
    }

    return true;
}

public String sortString(String s) {
    // Handle null or empty input
    if (s == null) {
        return null;
    }
    if (s.isEmpty()) {
        return "";
    }

    // This algorithm works for lowercase letters. If the input may contain other characters,
    // the following implementation will still function by considering the full 256 ASCII range.
    int[] count = new int[256];
    int totalLen = s.length();

    for (char ch : s.toCharArray()) {
        if (ch < 0 || ch >= 256) {
            // For non-ASCII characters, use a fallback: append them directly in order.
            // Since the problem description does not specify handling for such cases,
            // we simply ignore them for simplicity. Alternatively, one could throw an exception.
            continue;
        }
        count[ch]++;
    }

    StringBuilder result = new StringBuilder(totalLen);

    // Continue until all characters are consumed
    while (result.length() < totalLen) {
        // Ascending pass: pick smallest to largest
        for (int i = 0; i < 256; i++) {
            if (count[i] > 0) {
                result.append((char) i);
                count[i]--;
            }
        }
        // Descending pass: pick largest to smallest
        for (int i = 255; i >= 0; i--) {
            if (count[i] > 0) {
                result.append((char) i);
                count[i]--;
            }
        }
    }

    return result.toString();
}

