    if (words == null || words.length == 0) {
        return 0;
    }

    // Morse code representations for 'a' to 'z'
    final String[] morse = {".-","-...","-.-.","-..",".","..-.","--.",
                            "....","..",".---","-.-",".-..","--","-.",
                            "---",".--.","--.-",".-.", "...","-","..-",
                            "...-",".--","-..-","-.--","--.."};
    java.util.Set<String> uniqueSet = new java.util.HashSet<>();

    for (String word : words) {
        if (word == null || word.isEmpty()) {
            continue; // Skip null or empty words
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < word.length(); i++) {
            char c = word.charAt(i);
            // Ensure character is a lowercase letter; skip invalid chars
            if (c >= 'a' && c <= 'z') {
                sb.append(morse[c - 'a']);
            } else if (c >= 'A' && c <= 'Z') {
                sb.append(morse[c - 'A']);
            } else {
                // If the character is not a letter, ignore it
                continue;
            }
        }
        if (sb.length() > 0) {
            uniqueSet.add(sb.toString());
        }
    }
    return uniqueSet.size();
}

public boolean hasAllCodes(String s, int k) {
    if (k <= 0) {
        return true; // empty string always present
    }
    int n = s.length();
    if (n < k) {
        return false; // cannot contain all codes if shorter than k
    }
    // Number of possible binary codes of length k
    int totalCodes;
    try {
        totalCodes = 1 << k; // works safely for k < 31
    } catch (Exception e) {
        // In case of overflow (k too large), use a different approach
        // but problem constraints likely keep k small
        totalCodes = Integer.MAX_VALUE;
    }
    Set<Integer> seen = new HashSet<>(Math.min(totalCodes, n - k + 1));
    int mask = totalCodes - 1; // Keeps only the last k bits
    int value = 0;
    // Initialize the first window
    for (int i = 0; i < k; i++) {
        value = (value << 1) | (s.charAt(i) - '0');
    }
    seen.add(value);
    // Slide the window across the string
    for (int i = k; i < n; i++) {
        value = ((value << 1) & mask) | (s.charAt(i) - '0');
        seen.add(value);
    }
    return seen.size() == totalCodes;
}

