public int findMinFibonacciNumbers(int k) {
    if (k <= 0) return 0; // defensive, though k should be > 0
    int[] fib = new int[50]; // array large enough for all int Fibonacci numbers
    int n = 0;
    fib[n++] = 1; // F1
    fib[n++] = 1; // F2
    // Generate Fibonacci numbers up to k
    while (true) {
        long next = (long) fib[n - 1] + fib[n - 2];
        if (next > k || n >= fib.length) {
            break;
        }
        fib[n++] = (int) next;
    }
    int count = 0;
    int remaining = k;
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        if (fib[i] <= remaining) {
            remaining -= fib[i];
            count++;
        }
    }
    return count;
}

