    }
    // Build adjacency matrix
    boolean[][] adj = new boolean[m][m];
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < m; j++) {
            if (squares.contains(uniqueValues.get(i) + uniqueValues.get(j))) {
