    java.util.function.Function<StateKey, Long> solve = new java.util.function.Function<StateKey, Long>() {
        @Override
        public Long apply(StateKey key) {
            String memoKey = key.toString();
            if (memo.containsKey(memoKey)) {
                return memo.get(memoKey);
            }
            int remaining = 0;
            for (int c : key.counts) remaining += c;
            if (remaining == 0) {
                return 1L;
            }
