            sb.append(prevIdx).append('#');
            for (int i = 0; i < counts.length; i++) {
                sb.append(counts[i]).append(',');
            }
            return sb.toString();
        }
    }

    long result = solve.apply(new StateKey(-1, counts));
    return (int) result;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    int[] stack = new int[n + 1];
    int top = -1;
    long maxArea = 0;

    for (int i = 0; i <= n; i++) {
        int currHeight = (i == n) ? 0 : heights[i];
        while (top >= 0 && heights[stack[top]] > currHeight) {
            int height = heights[stack[top--]];
            int width = (top == -1) ? i : i - stack[top] - 1;
            long area = (long) height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack[++top] = i;
    }

    return (int) maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    // Handle null or empty matrix input
    if (mat == null || mat.length == 0 || mat[0] == null || mat[0].length == 0) {
        return new int[0];
    }

    int m = mat.length;
    int n = mat[0].length;
    int total = m * n;
    int[] result = new int[total];
    int index = 0;

    // Iterate over all possible diagonals (sum of indices)
    for (int sum = 0; sum <= m + n - 2; sum++) {
        // Determine the range of row indices for this diagonal
        int startRow = Math.max(0, sum - (n - 1));
        int endRow = Math.min(m - 1, sum);

        if (sum % 2 == 0) {
            // Even sum: traverse from bottom to top
            for (int i = endRow; i >= startRow; i--) {
                int j = sum - i;
                if (j >= 0 && j < n) {
                    result[index++] = mat[i][j];
                }
            }
        } else {
            // Odd sum: traverse from top to bottom
            for (int i = startRow; i <= endRow; i++) {
                int j = sum - i;
                if (j >= 0 && j < n) {
                    result[index++] = mat[i][j];
                }
            }
        }
    }

    return result;
}

